window.HOEREN_TESTS[13] = {"id":"familienfeste","name":"Familienfeste","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Hochzeitsgäste, willkommen zur Hochzeit von Mira und Tom. Das Hochzeitsessen beginnt um 18 Uhr im großen Saal. Wer mit dem Auto gekommen ist: Bitte parken Sie hinten beim Garten, der Vorplatz ist nur für die Familie. Das Tanzen startet um 21 Uhr — Sie haben also Zeit, sich zu erholen.","gender":"f","q":"Wo sollen Gäste mit Auto parken?","opts":["Vor dem Eingang.","Hinten beim Garten.","Auf der Straße."],"correct":1},{"transcript":"Hallo Sabine, hier ist Mama. Hey, Omas Geburtstag am Sonntag — Tante Eva kann doch nicht kommen, weil ihr Sohn krank wurde. Aber Onkel Karl kommt, das ist eine Überraschung für Oma. Kein neues Geschenk, Onkel Karl selbst ist die Überraschung. Bitte sag noch nichts, das ist ein Geheimnis. Komm bitte pünktlich um 14 Uhr. Danke!","gender":"f","q":"Was ist die Überraschung für Oma?","opts":["Onkel Karl kommt.","Tante Eva kommt.","Es gibt ein neues Geschenk."],"correct":0},{"transcript":"Hier ist die Konditorei Süßgebäck. Ihr Hochzeitskuchen ist bestellt: drei Stockwerke, weiße Schokolade mit Erdbeeren. Lieferung am Samstag um 14 Uhr direkt zum Festsaal. Nicht Sonntag früh, sondern Samstag um 14 Uhr. Falls es Probleme gibt, rufen Sie uns bis Freitagabend zurück. Ansonsten — wir freuen uns auf Ihren großen Tag. Danke!","gender":"m","q":"Wann wird der Kuchen geliefert?","opts":["Am Freitagabend.","Am Samstag um 14 Uhr.","Am Sonntag früh."],"correct":1},{"transcript":"Liebe Eltern und Großeltern, der Kindergeburtstag von Tim ist diesen Samstag, 14 Uhr, bei uns zu Hause. Bitte schicken Sie Ihr Kind mit Sportkleidung — nicht in schöner Kleidung, weil wir draußen spielen. Wir haben einen Magier eingeladen für 16 Uhr, das wird das Highlight. Kuchen und Geschenke sind organisiert.","gender":"f","q":"Was sollen die Kinder anziehen?","opts":["Sportkleidung.","Schöne Geburtstagskleidung.","Ein Kostüm."],"correct":0},{"transcript":"Hallo Schatz, hier ist Papa. Du, wegen Weihnachten — ich habe eine Idee. Statt zu Hause zu feiern, wie immer, könnten wir dieses Jahr ans Meer fahren? Sieben Tage Hotel mit Frühstück. Es ist eine schöne Abwechslung. Aber wenn du lieber zu Hause feierst, ist das auch okay. Sag deine Meinung.","gender":"m","q":"Was schlägt Papa vor?","opts":["Weihnachten zu Hause wie immer.","Weihnachten ganz absagen.","Weihnachten ans Meer fahren."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer übernimmt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Eva","gender":"f","text":"Hallo Sabine! Die goldene Hochzeit am Sonntag braucht noch einen Plan. Ich habe Papier und Stift hier."},{"speaker":"Sabine","gender":"f","text":"Endlich klären wir das zusammen, Eva. Der Tag soll für die beiden ruhig und schön werden."},{"speaker":"Eva","gender":"f","text":"Ich organisiere die Location. Der Gasthof am Markt ist seit gestern reserviert."},{"speaker":"Sabine","gender":"f","text":"Die Location passt gut zu uns. Ich koche das Hauptessen mit Braten und Kartoffeln."},{"speaker":"Eva","gender":"f","text":"Das Hauptessen duftet dann durchs ganze Haus. Bringt noch jemand einen Kuchen zum Kaffee mit?"},{"speaker":"Sabine","gender":"f","text":"Nein. Einen Kuchen bringt von uns niemand mit. Den Nachtisch plane ich allein."},{"speaker":"Eva","gender":"f","text":"Karl bringt seine Kamera mit."},{"speaker":"Sabine","gender":"f","text":"Karl macht die Fotos. Er stellt sich hinten hin und stört niemanden."},{"speaker":"Eva","gender":"f","text":"Fotos von jedem Tisch wären schön. Lukas kommt mit seiner Gitarre zum Fest."},{"speaker":"Sabine","gender":"f","text":"Lukas spielt Musik nach dem Essen. Er singt leise Lieder für die Gäste."},{"speaker":"Eva","gender":"f","text":"Musik macht den Abend richtig warm. Kauft noch jemand von uns das Geschenk für das Paar?"},{"speaker":"Sabine","gender":"f","text":"Das Geschenk kaufen wir nicht. Die Gäste legen zusammen Geld in eine Karte."},{"speaker":"Eva","gender":"f","text":"Robert übt schon seit vielen Tagen. Eine kurze Rede reicht völlig."},{"speaker":"Sabine","gender":"f","text":"Robert hält die Rede. Er spricht über die langen gemeinsamen Jahre."},{"speaker":"Eva","gender":"f","text":"Einverstanden. Ich schicke den Plan heute noch an die ganze Familie. Bis Sonntag."}],"options":[{"letter":"a","text":"schmückt den Saal"},{"letter":"b","text":"bringt einen Kuchen"},{"letter":"c","text":"macht die Fotos"},{"letter":"d","text":"kocht das Hauptessen"},{"letter":"e","text":"hält die Rede"},{"letter":"f","text":"organisiert die Location"},{"letter":"g","text":"fährt die Großeltern"},{"letter":"h","text":"kauft das Geschenk"},{"letter":"i","text":"spielt Musik"}],"items":[{"person":"Eva","correct":"f"},{"person":"Sabine","correct":"d"},{"person":"Karl","correct":"c"},{"person":"Lukas","correct":"i"},{"person":"Robert","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mutter","gender":"f","text":"Was wünschst du dir zum Geburtstag?"},{"speaker":"Kind","gender":"m","text":"Ich möchte ein neues Fahrrad."},{"speaker":"Mutter","gender":"f","text":"Ein Fahrrad ist viel Geld. Vielleicht ein kleineres Geschenk? Aber nichts wäre zu wenig."},{"speaker":"Kind","gender":"m","text":"Dann ein Skateboard? Das wollte ich auch schon lange."},{"speaker":"Mutter","gender":"f","text":"Skateboard geht. Ich kaufe eins. Aber erst zum Geburtstag!"},{"speaker":"Kind","gender":"m","text":"Juhu, Skateboard! Danke, Mama, du bist die Beste!"}],"q":"Was bekommt das Kind?","opts":["Ein Skateboard.","Ein neues Fahrrad.","Nichts."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Mein Mann hat morgen Geburtstag. Was kann ich kochen?"},{"speaker":"Freundin","gender":"f","text":"Sein Lieblingsessen ist Schnitzel, oder?"},{"speaker":"Frau","gender":"f","text":"Genau, aber Schnitzel mache ich oft. Ins Restaurant gehen wäre teuer. Vielleicht etwas Neues?"},{"speaker":"Freundin","gender":"f","text":"Lasagne ist immer gut für Geburtstage."},{"speaker":"Frau","gender":"f","text":"Lasagne kocht meine Schwiegermutter ständig. Ich mache Schnitzel — das ist sein Liebling, fertig."},{"speaker":"Freundin","gender":"f","text":"Gute Wahl! Schnitzel mit Kartoffelsalat, lecker!"}],"q":"Was kocht die Frau?","opts":["Sie geht ins Restaurant.","Lasagne.","Schnitzel."],"correct":2},{"lines":[{"speaker":"Anrufer","gender":"m","text":"Ich bestelle Blumen zur Hochzeit."},{"speaker":"Floristin","gender":"f","text":"Welche Farben?"},{"speaker":"Anrufer","gender":"m","text":"Weiß und rosa. Das ist klassisch."},{"speaker":"Floristin","gender":"f","text":"Wir können auch lila oder gelb anbieten, oder rote Rosen, falls Sie etwas Modernes möchten."},{"speaker":"Anrufer","gender":"m","text":"Nein, weiß und rosa bleibt — die Braut hat das so gewünscht, basta."},{"speaker":"Floristin","gender":"f","text":"Verstanden, weiß und rosa! Lieferung am Freitag, einverstanden?"}],"q":"Welche Blumen werden bestellt?","opts":["Lila und gelb.","Weiß und rosa.","Rote Rosen."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Tochter, kommst du zur Familienfeier am Samstag?"},{"speaker":"Tochter","gender":"f","text":"Eigentlich habe ich schon einen Termin mit Freunden. Beides geht leider nicht."},{"speaker":"Vater","gender":"m","text":"Oma wird sehr traurig sein. Sie kommt extra aus Hamburg."},{"speaker":"Tochter","gender":"f","text":"Okay, dann verschiebe ich die Freunde. Oma ist wichtiger, sie freut sich."},{"speaker":"Vater","gender":"m","text":"Danke, mein Schatz! Oma wird so glücklich sein!"}],"q":"Was macht die Tochter?","opts":["Sie geht zu den Freunden.","Sie geht zur Familienfeier.","Sie macht beides."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Wir machen unseren Hochzeitstag dieses Jahr besonders."},{"speaker":"Frau","gender":"f","text":"Was hast du geplant? Restaurant?"},{"speaker":"Mann","gender":"m","text":"Nein, etwas Besseres als Restaurant. Und nicht zu Hause, wirklich weg!"},{"speaker":"Frau","gender":"f","text":"Oh, das ist wundervoll! Paris, wirklich? Ich freue mich!"},{"speaker":"Mann","gender":"m","text":"Ja, Paris! Zwei Nächte, Hotel mit Frühstück, alles gebucht!"},{"speaker":"Frau","gender":"f","text":"Wunderbar! Unser Hochzeitstag in Paris, wie romantisch!"}],"q":"Was macht das Paar zum Hochzeitstag?","opts":["Ein Wochenende in Paris.","Ins Restaurant gehen.","Zu Hause feiern."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, die Hochzeiten plant. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie sind Hochzeitsplanerin seit 10 Jahren. Wie hat sich Ihr Beruf in dieser Zeit verändert?"},{"speaker":"Klein","gender":"f","text":"Sehr stark, vor 10 Jahren wollten alle eine klassische große Hochzeit mit 150 Gästen. Heute sehen wir mehr kleine Hochzeiten — 30 bis 50 Personen. Und immer mehr Paare heiraten im Ausland, statt zu Hause."},{"speaker":"Reporter","gender":"m","text":"Wie viele Hochzeiten planen Sie pro Jahr?"},{"speaker":"Klein","gender":"f","text":"Etwa 40 — also fast eine pro Woche im Sommer, aber im Winter habe ich Pause. Mai bis September ist die Hochsaison, da bin ich kaum zu Hause."},{"speaker":"Reporter","gender":"m","text":"Was ist Ihre wichtigste Regel?"},{"speaker":"Klein","gender":"f","text":"Das Paar ist König. Egal welche Wünsche — auch wenn ich denke, dass eine Idee nicht gut ist — die Entscheidung liegt bei ihnen. Ich gebe Rat, aber ich entscheide nicht."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"Klein","gender":"f","text":"Familienkonflikte! Wenn die Eltern der Braut und die Eltern des Bräutigams verschiedene Vorstellungen haben, wird es schwierig. Ich muss dann diplomatisch sein. Aber Wetterprobleme sind eigentlich häufiger."},{"speaker":"Reporter","gender":"m","text":"Haben Sie selbst geheiratet?"},{"speaker":"Klein","gender":"f","text":"Ja, vor drei Jahren — aber meine eigene Hochzeit habe ich von einer Kollegin planen lassen. Selbst wollte ich an dem Tag einfach Braut sein, nicht Planerin!"}],"items":[{"q":"Heute sind kleinere Hochzeiten häufiger als früher.","correct":"ja"},{"q":"Im Winter plant Frau Klein die meisten Hochzeiten.","correct":"nein"},{"q":"Familienkonflikte sind häufiger als Wetterprobleme.","correct":"nein"},{"q":"Sie hat ihre eigene Hochzeit selbst geplant.","correct":"nein"},{"q":"Bei wichtigen Entscheidungen entscheidet das Paar selbst.","correct":"ja"}]}]};
